css='''*{box-sizing:border-box}body{margin:0;font:15px/1.6 system-ui,sans-serif;color:#172b45;background:#f3f6fa}header{background:#102b4e;color:white;padding:24px 32px;display:flex;justify-content:space-between;gap:20px;align-items:center}header strong{font-size:23px}header small{display:block;color:#c3d3e8}aside{width:245px;padding:24px 16px;border-right:1px solid #dce4ee;background:white;position:fixed;top:0;bottom:0;overflow:auto;padding-top:150px}header{position:relative;z-index:1}nav{display:grid;gap:8px}button{font:inherit;border:1px solid #cbd7e5;border-radius:7px;background:white;color:#173554;padding:10px 15px;cursor:pointer}button:hover{background:#edf3fa}button:focus-visible,input:focus,textarea:focus,select:focus{outline:3px solid #82b2f3;outline-offset:2px}.active,.primary,.selected{background:#123c6a!important;color:white!important;border-color:#123c6a}nav button{text-align:left}.danger{color:#a32e29}.shell{margin-left:245px;padding:28px 36px;max-width:1550px}h1{font-size:28px;margin:0 0 18px}h2{font-size:18px;margin:0 0 14px}h3{font-size:16px}p{white-space:pre-wrap;overflow-wrap:anywhere}.card{background:white;border:1px solid #dce4ee;border-radius:10px;padding:22px;margin:0 0 18px}.card .card{background:#f8fafc;box-shadow:none}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.metrics .card{padding:18px}.metrics h2{font-size:13px;color:#536980}.metrics strong{font-size:32px}.field{display:block;margin:14px 0}.field span{display:block;font-size:13px;font-weight:600;margin-bottom:6px}input:not([type=checkbox]),textarea,select{width:100%;border:1px solid #b8c8da;border-radius:6px;padding:10px;font:inherit;background:white;color:#172b45}textarea{min-height:85px;resize:vertical}input[type=checkbox]{width:19px;height:19px}.check{display:flex;align-items:center;gap:10px;margin:12px 0}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}.scores button{min-width:48px}.scores .selected{outline:3px solid #b6d2f3}details{background:#eef4fa;padding:14px;border-radius:6px;margin:14px 0}summary{cursor:pointer;font-weight:600}progress{width:100%;height:9px;accent-color:#194c83}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px 6px;border-bottom:1px solid #dce4ee;text-align:left;overflow-wrap:anywhere}.notice{background:#e8f0f9;padding:12px 18px;margin-bottom:16px;border-radius:6px}.notice:empty{display:none}.error{background:#fff0ed;color:#982c20}#saveStatus{font-size:12px}.privacy{font-size:12px;color:#536980;margin-top:24px}.backup{margin-top:25px;display:grid;gap:9px}.fileLabel{border:1px solid #cbd7e5;border-radius:7px;padding:10px;cursor:pointer}.fileLabel input{font-size:12px}.draft{color:#a32e29;border:2px solid #a32e29;padding:12px;font-weight:bold;margin-bottom:18px}#report{max-width:1000px}#report:empty{display:none}@media(max-width:850px){header{padding:18px;display:block}header strong{font-size:19px}aside{position:static;width:100%;padding:12px}nav{display:flex;overflow:auto}nav button{white-space:nowrap}.backup{display:flex;flex-wrap:wrap;margin-top:12px}.fileLabel{max-width:260px}.shell{margin:0;padding:20px 12px}.privacy{margin:8px 0}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.card{padding:16px}th,td{font-size:11px;padding:6px 3px}.actions button{flex-grow:1}}@page{size:A4;margin:14mm}@media print{body{background:white;color:black;font-size:10pt}header,aside,.shell>h1,#notice,#app>.actions{display:none!important}.shell{margin:0;padding:0;max-width:none}#app>*:not(#report){display:none!important}#report{display:block;max-width:none}#report .card{border:0;border-bottom:1px solid #bbb;border-radius:0;margin:0 0 8mm;padding:0 0 4mm}h1,h2,h3{break-after:avoid}tr,p{break-inside:avoid}table{font-size:9pt}button,input,textarea,select{display:none!important}.draft{font-size:14pt}#report h1{display:block!important;font-size:20pt}}'''
html='''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BARAKA Express — Recruitment Assessment System</title><style>'''+css+'''</style></head><body><header><div><strong>BARAKA Express</strong><small>Recruitment Assessment System</small><small>Structured Interview &amp; Competency Evaluation</small></div><div id="saveStatus" role="status">Membuka penyimpanan…</div></header><aside><nav aria-label="Navigasi utama"></nav><div class="backup"><button id="backup">Backup JSON</button><label class="fileLabel">Import JSON<input id="import" type="file" accept=".json,application/json"></label><button id="csv">Export CSV</button><button id="reset" class="danger">Reset database</button></div><p class="privacy">Data tersimpan di browser/perangkat ini, tanpa sinkronisasi atau login. Penyimpanan browser bukan backup permanen. Gunakan satu tab dan ekspor backup rutin. Batasi akses perangkat dan simpan data pribadi seperlunya.</p></aside><main class="shell"><h1 id="pageTitle">Dashboard</h1><div id="notice" role="alert" class="notice"></div><div id="app"></div><div id="report"></div></main><script>'''
